        public static void ApplyTheme()
        {
            string xaml = ControlTheme;
            string[] names = { "Page", "Surface", "Input", "Text", "Muted", "Edge", "Accent", "Soft", "Hover", "Disabled", "Thumb" };
            string[] light = { "#F7F7F7", "#FFFFFF", "#FFFFFF", "#202445", "#646879", "#E1E1E5", "#0057FF", "#EAF0FF", "#F0F0F3", "#9496A0", "#B7B8C2" };
            string[] dark = { "#1C1C1E", "#272729", "#2D2D30", "#F3F3F5", "#B2B3BD", "#3D3D42", "#82AAFF", "#28364E", "#323235", "#777780", "#616169" };
            for (int i = 0; i < names.Length; i++) xaml = xaml.Replace("@" + names[i] + "@", UiPreferences.Dark ? dark[i] : light[i]);
            Application.Current.Resources.MergedDictionaries.Clear();
            Application.Current.Resources.MergedDictionaries.Add((ResourceDictionary)XamlReader.Parse(xaml));
            Application.Current.Resources.MergedDictionaries.Add((ResourceDictionary)XamlReader.Parse(NativeControlTheme.Replace("@AccentText@", UiPreferences.Dark ? "#111826" : "#FFFFFF")));
            MainWindow.RefreshPalette();
            foreach (Window window in Application.Current.Windows) { ThemeNativeWindow(window); var main = window as MainWindow; if (main != null) main.UpdateTrayAppearance(); }
        }
        [DllImport("dwmapi.dll")] private static extern int DwmSetWindowAttribute(IntPtr window, int attribute, ref int value, int size);
        internal static void ThemeNativeWindow(Window window)
        {
            window.Icon = ApplicationIcon.WindowImage;
            var handle = new WindowInteropHelper(window).Handle; if (handle == IntPtr.Zero) return;
            int dark = UiPreferences.Dark ? 1 : 0;
            try
            {
                if (DwmSetWindowAttribute(handle, 20, ref dark, 4) != 0) DwmSetWindowAttribute(handle, 19, ref dark, 4);
                int corner = 2; DwmSetWindowAttribute(handle, 33, ref corner, 4);
                int backdrop = 2; DwmSetWindowAttribute(handle, 38, ref backdrop, 4);
                int caption = UiPreferences.Dark ? 0x00222020 : 0x00F3F3F3; DwmSetWindowAttribute(handle, 35, ref caption, 4);
                int text = UiPreferences.Dark ? 0x00F5F3F3 : 0x00452420; DwmSetWindowAttribute(handle, 36, ref text, 4);
            }
            catch (DllNotFoundException) { } catch (EntryPointNotFoundException) { }
        }

